public class Main {
    record Node(int value, Node left, Node right) {
    }

    static void inorder(Node node, StringBuilder out) {
        if (node == null) {
            return;
        }
        inorder(node.left(), out);
        out.append(node.value()).append(' ');
        inorder(node.right(), out);
    }

    public static void main(String[] args) {
        Node root = new Node(4, new Node(2, new Node(1, null, null), new Node(3, null, null)), new Node(6, null, new Node(7, null, null)));
        StringBuilder out = new StringBuilder();
        inorder(root, out);
        System.out.println(out.toString().trim());
    }
}

public class Main {
    record Node(int value, Node left, Node right) {
    }

    static void preorder(Node node, StringBuilder out) {
        if (node == null) {
            return;
        }
        out.append(node.value()).append(' ');
        preorder(node.left(), out);
        preorder(node.right(), out);
    }

    public static void main(String[] args) {
        Node root = new Node(4, new Node(2, new Node(1, null, null), new Node(3, null, null)), new Node(6, null, new Node(7, null, null)));
        StringBuilder out = new StringBuilder();
        preorder(root, out);
        System.out.println(out.toString().trim());
    }
}

